    'ka_q_sci_1_prompt': 'Why does liquid water expand when it freezes into ice, allowing aquatic life to survive winter beneath frozen lakes?',
    'ka_q_sci_1_opt_a': 'Water molecules lock into an open hexagonal hydrogen-bond crystal lattice that is ~9% less dense than liquid water',
    'ka_q_sci_1_opt_b': 'Dissolved oxygen bubbles inflate the ice from the lakebed upward',
    'ka_q_sci_1_opt_c': 'Winter atmospheric pressure compresses liquid water below while stretching surface molecules',
    'ka_q_sci_1_opt_d': 'Cold water absorbs nitrogen from the air to float like foam',
    'ka_q_sci_1_fact_title': 'Hexagonal Ice Lattice & Winter Lake Survival',
    'ka_q_sci_1_explain': 'Unlike almost every other substance, water reaches maximum density at 4°C. Below 4°C, hydrogen bonds force H2O molecules into a spacious hexagonal crystal lattice (~9% less dense), making ice float as a thermal blanket that insulates fish and aquatic plants below.',
    'ka_q_sci_1_book_title': 'Water: A Natural History',
    'ka_q_sci_1_book_author': 'Alice Outwater',
    'ka_q_sci_2_prompt': 'Roughly how long does a photon of sunlight take to cross the vacuum of space from the Sun\'s surface to Earth?',
    'ka_q_sci_2_opt_a': 'About 8 minutes and 20 seconds',
    'ka_q_sci_2_opt_b': 'About 1.3 seconds',
    'ka_q_sci_2_opt_c': 'About 4.2 years',
    'ka_q_sci_2_opt_d': 'Instantly (0 seconds)',
    'ka_q_sci_2_fact_title': 'Sunlight\'s 8-Minute 20-Second Journey to Earth',
    'ka_q_sci_2_explain': 'Earth orbits at ~149.6 million km from the Sun. Travelling at ~299,792 km/s in a vacuum, light from the solar photosphere reaches your eyes in ~8 minutes 20 seconds (after spending thousands of years bouncing through the Sun\'s dense radiative interior).',
    'ka_q_sci_2_book_title': 'Cosmos',
    'ka_q_sci_2_book_author': 'Carl Sagan',
    'ka_q_nat_1_prompt': 'How do forest trees share carbon, water, and chemical defense signals underground across the "Wood Wide Web"?',
    'ka_q_nat_1_opt_a': 'Through symbiotic mycorrhizal fungal networks linking tree roots',
    'ka_q_nat_1_opt_b': 'Through magnetic iron particles vibrating in bedrock',
    'ka_q_nat_1_opt_c': 'Through underground pollen rivers',
    'ka_q_nat_1_opt_d': 'Through hollow root tunnels carved by earthworms',
    'ka_q_nat_1_fact_title': 'Mycorrhizal Networks & Mother Trees',
    'ka_q_nat_1_explain': 'Thread-like mycorrhizal fungi wrap around and fuse with tree roots, trading soil minerals for sugars. Older "hub" or mother trees use this fungal network to send carbon, nitrogen, and pest-warning signals to shaded seedlings.',
    'ka_q_nat_1_book_title': 'Finding the Mother Tree',
    'ka_q_nat_1_book_author': 'Suzanne Simard',
    'ka_q_nat_2_prompt': 'Which marine mammal sleeps with one brain hemisphere at a time so it can keep swimming and surfacing to breathe?',
    'ka_q_nat_2_opt_a': 'Bottlenose dolphin',
    'ka_q_nat_2_opt_b': 'Sea otter',
    'ka_q_nat_2_opt_c': 'Polar bear',
    'ka_q_nat_2_opt_d': 'Harbor seal',
    'ka_q_nat_2_fact_title': 'Unihemispheric Slow-Wave Sleep in Dolphins',
    'ka_q_nat_2_explain': 'Dolphins practice unihemispheric slow-wave sleep: one half of the brain enters deep rest while the other half stays awake to control conscious breathing at the surface and keep one eye open watching for pod mates.',
    'ka_q_nat_2_book_title': 'Why We Sleep',
    'ka_q_nat_2_book_author': 'Matthew Walker',
    'ka_q_geo_1_prompt': 'Which Indonesian strait marks the famous biogeographical Wallace Line separating Asian and Australasian wildlife?',
    'ka_q_geo_1_opt_a': 'The Lombok Strait (between Bali and Lombok) & Makassar Strait',
    'ka_q_geo_1_opt_b': 'The Sunda Strait (between Java and Sumatra)',
    'ka_q_geo_1_opt_c': 'The Malacca Strait',
    'ka_q_geo_1_opt_d': 'The Karimata Strait',
    'ka_q_geo_1_fact_title': 'The Wallace Line & Deep-Sea Biogeography',
    'ka_q_geo_1_explain': 'Even during Ice Age low sea levels when Sumatra, Java, Bali, and Borneo were joined to mainland Asia, the deep Lombok Strait remained an ocean barrier—keeping Asian tigers and woodpeckers west of the line and cockatoos and marsupials east.',
    'ka_q_geo_1_book_title': 'The Malay Archipelago',
    'ka_q_geo_1_book_author': 'Alfred Russel Wallace',
    'ka_q_geo_2_prompt': 'Where on Earth is the longest continuous mountain range located?',
    'ka_q_geo_2_opt_a': 'Beneath the oceans along the Mid-Ocean Ridge (~65,000 km)',
    'ka_q_geo_2_opt_b': 'The Andes across South America (~7,000 km)',
    'ka_q_geo_2_opt_c': 'The Himalayas and Karakoram across Asia',
    'ka_q_geo_2_opt_d': 'The Rocky Mountains across North America',
    'ka_q_geo_2_fact_title': 'The 65,000-km Submarine Mid-Ocean Ridge',
    'ka_q_geo_2_explain': 'Winding through every ocean basin like the seam on a baseball, the Mid-Ocean Ridge is an underwater volcanic mountain chain ~65,000 km long where tectonic plates pull apart and birth fresh oceanic crust.',
    'ka_q_geo_2_book_title': 'Annals of the Former World',
    'ka_q_geo_2_book_author': 'John McPhee',
    'ka_q_hist_1_prompt': 'Why did thousands of ancient Mesopotamian cuneiform records survive for over 4,000 years while later papyrus libraries vanished?',
    'ka_q_hist_1_opt_a': 'They were pressed into clay tablets that baked rock-hard whenever palaces burned',
    'ka_q_hist_1_opt_b': 'They were engraved on solid platinum plates',
    'ka_q_hist_1_opt_c': 'They were frozen inside alpine glaciers',
    'ka_q_hist_1_opt_d': 'They were laminated in natural tree rubber',
    'ka_q_hist_1_fact_title': 'Cuneiform Clay Tablets & Fire Preservation',
    'ka_q_hist_1_explain': 'Scribes in Sumer, Babylon, and Assyria pressed wedge-shaped reed styluses into soft clay. Ironically, ancient fires that destroyed wooden buildings kiln-fired the clay tablets into durable ceramic archives.',
    'ka_q_hist_1_book_title': ' Sapiens: A Brief History of Humankind',
    'ka_q_hist_1_book_author': 'Yuval Noah Harari',
    'ka_q_hist_2_prompt': 'How did ancient Austronesian and Polynesian wayfinders navigate thousands of kilometers of open Pacific ocean without magnetic compasses?',
    'ka_q_hist_2_opt_a': 'Reading horizon star paths, ocean swell refraction patterns & cloud/seabird cues',
    'ka_q_hist_2_opt_b': 'Following underwater volcanic cable trenches',
    'ka_q_hist_2_opt_c': 'Drifting randomly with seasonal monsoons',
    'ka_q_hist_2_opt_d': 'Using glass sextants and mechanical chronometers',
    'ka_q_hist_2_fact_title': 'Austronesian Star Compasses & Wave Piloting',
    'ka_q_hist_2_explain': 'Master wayfinders memorized 32-point horizon star compasses, felt subtle cross-swells refracting off distant islands through the hull of their outrigger canoes, and spotted lagoon-green reflections on the undersides of clouds.',
    'ka_q_hist_2_book_title': 'The Wayfinders: Why Ancient Wisdom Matters',
    'ka_q_hist_2_book_author': 'Wade Davis',
    'ka_q_cult_1_prompt': 'In traditional Indonesian UNESCO-recognized Batik tulis, what is the role of the copper "canting" tool?',
    'ka_q_cult_1_opt_a': 'Drawing hot liquid beeswax (malam) onto cloth as a dye-resist pattern',
    'ka_q_cult_1_opt_b': 'Spinning raw cotton into fine yarn',
    'ka_q_cult_1_opt_c': 'Polishing finished silk with river stones',
    'ka_q_cult_1_opt_d': 'Boiling indigo leaves in clay vats',
    'ka_q_cult_1_fact_title': 'Philosophy & Craft of Indonesian Batik Canting',
    'ka_q_cult_1_explain': 'A canting holds warm liquid wax (malam) in a small copper reservoir with a fine spout. Artisans draw intricate dots and lines that resist dye baths, layering colors to create philosophical motifs like Kawung and Parang.',
    'ka_q_cult_1_book_title': 'Batik: Fabled Cloth of Java',
    'ka_q_cult_1_book_author': 'Inger McCabe Elliott',
    'ka_q_cult_2_prompt': 'In the Japanese craft philosophy of "Kintsugi", how are fractured ceramic tea bowls traditionally restored?',
    'ka_q_cult_2_opt_a': 'Mended with urushi lacquer dusted with powdered gold, honoring the repair as part of the bowl\'s story',
    'ka_q_cult_2_opt_b': 'Crushed into powder to make new porcelain slip',
    'ka_q_cult_2_opt_c': 'Hidden under thick opaque black enamel so cracks disappear',
    'ka_q_cult_2_opt_d': 'Clamped with iron rivets and buried in sand',
    'ka_q_cult_2_fact_title': 'Kintsugi & Wabi-Sabi Golden Joinery',
    'ka_q_cult_2_explain': 'Originating in 15th-century Japan, Kintsugi ("golden joinery") bonds broken pottery with natural urushi tree sap lacquer and illuminates the seams with gold dust—celebrating resilience and imperfection rather than hiding damage.',
    'ka_q_cult_2_book_title': 'Wabi-Sabi for Artists, Designers, Poets & Philosophers',
    'ka_q_cult_2_book_author': 'Leonard Koren',
