    'bp_p_pat_1_title': '90° Phase Rotation Cycle',
    'bp_p_pat_1_prompt': 'Observe the rotating moon-phase disc sequence:  ◐  →  ◓  →  ◑  →  ?  Which symbol completes the 90° clockwise cycle?',
    'bp_p_pat_1_opt_a': '◒ (Bottom half illuminated)',
    'bp_p_pat_1_opt_b': '◐ (Left half illuminated)',
    'bp_p_pat_1_opt_c': '◓ (Top half illuminated)',
    'bp_p_pat_1_opt_d': '● (Fully illuminated)',
    'bp_p_pat_1_explain': 'Each step rotates the illuminated half by 90° clockwise: Left (◐) → Top (◓) → Right (◑) → Bottom (◒). Mental rotation warms up visual working memory before deep work.',
    'bp_p_pat_2_title': 'Matrix Symmetry & Fill Parity',
    'bp_p_pat_2_prompt': 'Row 1:  △  ▲  △   |   Row 2:  ○  ●  ○   |   Row 3:  □  ■  ?   Which tile completes Row 3?',
    'bp_p_pat_2_opt_a': '□ (Hollow square)',
    'bp_p_pat_2_opt_b': '■ (Filled square)',
    'bp_p_pat_2_opt_c': '○ (Hollow circle)',
    'bp_p_pat_2_opt_d': '▲ (Filled triangle)',
    'bp_p_pat_2_explain': 'Every row keeps a constant shape (triangle, circle, square) while alternating fill parity symmetrically: Hollow – Filled – Hollow (□ ■ □).',
    'bp_p_seq_1_title': 'Fibonacci Botanical Spiral Step',
    'bp_p_seq_1_prompt': 'Sunflower spirals and pinecones grow along the sequence:  1,  1,  2,  3,  5,  8,  13,  ?   What number comes next?',
    'bp_p_seq_1_opt_a': '21 (8 + 13)',
    'bp_p_seq_1_opt_b': '19 (6 + 13)',
    'bp_p_seq_1_opt_c': '24 (11 + 13)',
    'bp_p_seq_1_opt_d': '26 (13 × 2)',
    'bp_p_seq_1_explain': 'In the Fibonacci sequence, each term is the sum of the two preceding numbers: 8 + 13 = 21. Spotting additive recurrences primes analytical focus.',
    'bp_p_seq_2_title': 'Triangular First-Difference Progression',
    'bp_p_seq_2_prompt': 'Look at the expanding intervals in:  2,  4,  7,  11,  16,  ?   Which number continues the pattern?',
    'bp_p_seq_2_opt_a': '22 (+6 step)',
    'bp_p_seq_2_opt_b': '20 (+4 step)',
    'bp_p_seq_2_opt_c': '21 (+5 step)',
    'bp_p_seq_2_opt_d': '24 (+8 step)',
    'bp_p_seq_2_explain': 'The differences between consecutive terms grow by +1 each step: +2, +3, +4, +5, so the next step is 16 + 6 = 22.',
    'bp_p_spa_1_title': '3D Cube Net Opposite-Face Folding',
    'bp_p_spa_1_prompt': 'In a flat cross-shaped 6-square cube net, ★ sits on the center square and ● sits 2 squares to its right (separated by 1 middle square). When folded into a 3D cube, where does ● land relative to ★?',
    'bp_p_spa_1_opt_a': 'Directly on the opposite parallel face to ★',
    'bp_p_spa_1_opt_b': 'On the same face overlapping ★',
    'bp_p_spa_1_opt_c': 'Touching ★ along the top edge',
    'bp_p_spa_1_opt_d': 'Touching ★ along the left edge',
    'bp_p_spa_1_explain': 'In any orthogonal cube net, two squares separated by exactly one square in a straight line always fold 90° twice (180° total) to become opposite parallel faces.',
    'bp_p_spa_2_title': 'Horizontal Mirror Axis Reflection',
    'bp_p_spa_2_prompt': 'An L-shaped corner tile points Up and Right (┗). If you reflect it horizontally across a vertical mirror line on its right, which orientation results?',
    'bp_p_spa_2_opt_a': '┛ (Points Up and Left)',
    'bp_p_spa_2_opt_b': '┏ (Points Down and Right)',
    'bp_p_spa_2_opt_c': '┓ (Points Down and Left)',
    'bp_p_spa_2_opt_d': '┗ (Unchanged Up and Right)',
    'bp_p_spa_2_explain': 'Reflecting across a vertical mirror line preserves vertical orientation (Up stays Up) while inverting horizontal direction (Right flips to Left: ┗ → ┛).',
