    'exp_dcp_sketch_1_title': 'Mug & Morning Steam Contour',
    'exp_dcp_sketch_1_prompt': 'Draw the nearest cup, glass, or teapot using one continuous loose line without lifting your pen for a minute, then add simple shading.',
    'exp_dcp_sketch_1_tip': 'Wobbly lines carry more warmth than ruler-straight edges.',
    'exp_dcp_sketch_2_title': 'Pocket Window Frame',
    'exp_dcp_sketch_2_prompt': 'Sketch just one rectangle of whatever you see out a window or doorway right now—rooftops, leaves, or clouds.',
    'exp_dcp_sketch_2_tip': 'Focus on big shapes first; tiny details are optional.',
    'exp_dcp_sketch_3_title': 'Three Everyday Objects',
    'exp_dcp_sketch_3_prompt': 'Pick three small items within arm’s reach (keys, leaf, spoon, headphones) and sketch them side by side as tiny study icons.',
    'exp_dcp_sketch_3_tip': 'Any scrap paper or margin works cleanly.',
    'exp_dcp_poetry_1_title': 'Three-Line Weather Haiku',
    'exp_dcp_poetry_1_prompt': 'Write three short lines capturing today’s sky, air temperature, and one tiny indoor sound around you.',
    'exp_dcp_poetry_1_tip': 'Ignore strict syllable counting if another rhythm feels truer.',
    'exp_dcp_poetry_2_title': 'Six-Word Moment',
    'exp_dcp_poetry_2_prompt': 'Distill how this exact hour feels into three micro-sentences of six words each.',
    'exp_dcp_poetry_2_tip': 'Concrete nouns and verbs shine brighter than big adjectives.',
    'exp_dcp_poetry_3_title': 'Letter to a Quiet Object',
    'exp_dcp_poetry_3_prompt': 'Write 4 short lines thanking an ordinary everyday object—your desk lamp, kettle, or worn shoes—for keeping pace with you.',
    'exp_dcp_poetry_3_tip': 'Playful and gentle beats polished.',
    'exp_dcp_obs_1_title': 'Five Quiet Colors Nearby',
    'exp_dcp_obs_1_prompt': 'Look slowly around the room and name five specific shades you hadn’t noticed today (like dusty sage, warm brass, or slate shadow).',
    'exp_dcp_obs_1_tip': 'Pair each color with one word for how it feels.',
    'exp_dcp_obs_2_title': 'Two-Minute Sound Map',
    'exp_dcp_obs_2_prompt': 'Close your eyes for 60 seconds, then jot down the farthest sound, the closest sound, and the quietest sound you heard.',
    'exp_dcp_obs_2_tip': 'Even refrigerator hums or distant birds make great field notes.',
    'exp_dcp_obs_3_title': 'Texture & Light Inventory',
    'exp_dcp_obs_3_prompt': 'Describe three surfaces near you—smooth ceramic, rough wood grain, soft cotton—and where light catches their edges.',
    'exp_dcp_obs_3_tip': 'Write as if explaining them to someone visiting for the first time.',
    'exp_dcp_shadow_1_title': 'Window Blind Geometry',
    'exp_dcp_shadow_1_prompt': 'Find one beam of sunlight or lamp light crossing a wall, floor, or desk and frame a photo focusing purely on the shadow lines.',
    'exp_dcp_shadow_1_tip': 'Lower exposure slightly on your phone to deepen contrast.',
    'exp_dcp_shadow_2_title': 'Cup or Plant Silhouette',
    'exp_dcp_shadow_2_prompt': 'Place a glass, leaf, or mug beside a bright window or desk lamp and capture its stretched shadow rather than the object itself.',
    'exp_dcp_shadow_2_tip': 'Try tilting the camera closer to the surface for dramatic angles.',
    'exp_dcp_shadow_3_title': 'Passing Texture in Half-Light',
    'exp_dcp_shadow_3_prompt': 'Notice a dappled shadow from leaves, curtains, or railings and take one still photo, then note what mood the pattern evokes.',
    'exp_dcp_shadow_3_tip': 'Black-and-white preview helps highlight pure light and shadow.',
