    'mw_l3_nonclinical_disclaimer': 'Bacaan edukatif berbahasa sederhana untuk refleksi sehari-hari—bukan nasihat medis atau diagnosis klinis.',
    'mw_l3_edu_section_title': 'Pemahaman Sehari-Hari & Panduan Offline',
