    'ka_q_sci_1_prompt': 'Mengapa air cair memuai saat membeku menjadi es, sehingga kehidupan air dapat bertahan hidup di bawah danau beku saat musim dingin?',
    'ka_q_sci_1_opt_a': 'Molekul air membentuk kisi kristal ikatan hidrogen heksagonal terbuka yang ~9% lebih ringan dari air cair',
    'ka_q_sci_1_opt_b': 'Gelembung oksigen terlarut mengembangkan es dari dasar danau ke atas',
    'ka_q_sci_1_opt_c': 'Tekanan udara musim dingin memampatkan air di bawah sambil meregangkan permukaan',
    'ka_q_sci_1_opt_d': 'Air dingin menyerap nitrogen dari udara sehingga mengapung seperti busa',
    'ka_q_sci_1_fact_title': 'Kisi Es Heksagonal & Kelangsungan Hidup Danau Musim Dingin',
    'ka_q_sci_1_explain': 'Berbeda dari hampir semua zat lain, air mencapai kerapatan maksimum pada 4°C. Di bawah 4°C, ikatan hidrogen menyusun molekul H2O menjadi kisi kristal heksagonal berongga (~9% lebih ringan), membuat es mengapung sebagai selimut termal yang melindungi ikan di bawahnya.',
    'ka_q_sci_1_book_title': 'Water: A Natural History',
    'ka_q_sci_1_book_author': 'Alice Outwater',
