    'ka_q_sci_2_opt_d': 'Seketika (0 detik)',
    'ka_q_sci_2_fact_title': 'Perjalanan 8 Menit 20 Detik Cahaya Matahari ke Bumi',
    'ka_q_sci_2_explain': 'Bumi mengorbit sekitar 149,6 juta km dari Matahari. Melaju ~299.792 km/detik di ruang hampa, cahaya dari fotosfer Matahari tiba di mata kita dalam ~8 menit 20 detik (setelah ribuan tahun memantul di zona radiatif Matahari yang padat).',
    'ka_q_sci_2_book_title': 'Cosmos',
    'ka_q_sci_2_book_author': 'Carl Sagan',
    'ka_q_nat_1_prompt': 'Bagaimana pepohonan hutan berbagi karbon, air, dan sinyal pertahanan di bawah tanah melalui "Wood Wide Web"?',
    'ka_q_nat_1_opt_a': 'Melalui jaringan jamur mikoriza simbiotik yang menghubungkan akar pohon',
    'ka_q_nat_1_opt_b': 'Melalui partikel besi magnetik yang bergetar di batuan dasar',
    'ka_q_nat_1_opt_c': 'Melalui aliran serbuk sari bawah tanah',
    'ka_q_nat_1_opt_d': 'Melalui terowongan akar berongga yang digali cacing tanah',
    'ka_q_nat_1_fact_title': 'Jaringan Mikoriza & Pohon Induk',
    'ka_q_nat_1_explain': 'Jamur mikoriza berserat halus menyatu dengan akar pohon, menukar mineral tanah dengan gula hasil fotosintesis. Pohon induk tua menggunakan jaringan jamur ini untuk mengirim karbon, nitrogen, dan sinyal peringatan hama ke bibit pohon di tempat teduh.',
    'ka_q_nat_1_book_title': 'Finding the Mother Tree',
    'ka_q_nat_1_book_author': 'Suzanne Simard',
    'ka_q_nat_2_prompt': 'Mamalia laut mana yang tidur dengan satu belahan otak secara bergantian agar tetap bisa berenang dan muncul ke permukaan untuk bernapas?',
    'ka_q_nat_2_opt_a': 'Lumba-lumba hidung botol',
    'ka_q_nat_2_opt_b': 'Berang-berang laut',
    'ka_q_nat_2_opt_c': 'Beruang kutub',
    'ka_q_nat_2_opt_d': 'Anjing laut pelabuhan',
    'ka_q_nat_2_fact_title': 'Tidur Gelombang Lambat Unihemisfer pada Lumba-Lumba',
    'ka_q_nat_2_explain': 'Lumba-lumba menerapkan tidur gelombang lambat unihemisfer: satu belahan otak beristirahat lelap sementara belahan lainnya tetap terjaga untuk mengatur pernapasan sadar di permukaan dan menjaga satu mata tetap terbuka mengawasi kawanan.',
    'ka_q_nat_2_book_title': 'Why We Sleep',
    'ka_q_nat_2_book_author': 'Matthew Walker',
    'ka_q_geo_1_prompt': 'Selat di Indonesia manakah yang menjadi penanda utama Garis Wallace yang memisahkan satwa Asia dan Australasia?',
    'ka_q_geo_1_opt_a': 'Selat Lombok (antara Bali dan Lombok) & Selat Makassar',
    'ka_q_geo_1_opt_b': 'Selat Sunda (antara Jawa dan Sumatra)',
    'ka_q_geo_1_opt_c': 'Selat Malaka',
    'ka_q_geo_1_opt_d': 'Selat Karimata',
    'ka_q_geo_1_fact_title': 'Garis Wallace & Biogeografi Laut Dalam',
    'ka_q_geo_1_explain': 'Bahkan saat permukaan laut turun di Zaman Es ketika Sumatra, Jawa, Bali, dan Kalimantan menyatu dengan daratan Asia, Selat Lombok yang dalam tetap menjadi palung pemisah—menjaga harimau dan burung pelatuk Asia di barat garis serta kakatua dan marsupial di timur.',
    'ka_q_geo_1_book_title': 'The Malay Archipelago',
    'ka_q_geo_1_book_author': 'Alfred Russel Wallace',
    'ka_q_geo_2_prompt': 'Di manakah letak rangkaian pegunungan terpanjang yang menyambung tanpa putus di Bumi?',
    'ka_q_geo_2_opt_a': 'Di dasar samudra sepanjang Punggung Tengah Samudra (~65.000 km)',
    'ka_q_geo_2_opt_b': 'Pegunungan Andes di Amerika Selatan (~7.000 km)',
    'ka_q_geo_2_opt_c': 'Pegunungan Himalaya dan Karakoram di Asia',
    'ka_q_geo_2_opt_d': 'Pegunungan Rocky di Amerika Utara',
    'ka_q_geo_2_fact_title': 'Punggung Tengah Samudra Bawah Laut Sepanjang 65.000 km',
    'ka_q_geo_2_explain': 'Membentang melintasi dasar samudra seperti jahitan bola kasti, Punggung Tengah Samudra (Mid-Ocean Ridge) adalah rantai pegunungan vulkanik bawah laut sepanjang ~65.000 km tempat lempeng tektonik saling menjauh dan melahirkan kerak samudra baru.',
    'ka_q_geo_2_book_title': 'Annals of the Former World',
    'ka_q_geo_2_book_author': 'John McPhee',
    'ka_q_hist_1_prompt': 'Mengapa ribuan catatan aksara paku (cuneiform) Mesopotamia kuno bertahan lebih dari 4.000 tahun sementara perpustakaan papirus musnah?',
    'ka_q_hist_1_opt_a': 'Ditulis pada lempung tanah liat yang justru terpanggang sekeras batu saat istana terbakar',
    'ka_q_hist_1_opt_b': 'Diukir pada lempengan platina murni',
    'ka_q_hist_1_opt_c': 'Dibekukan di dalam gletser pegunungan',
    'ka_q_hist_1_opt_d': 'Dilapisi karet pohon alami',
    'ka_q_hist_1_fact_title': 'Lempung Aksara Paku & Pelestarian oleh Api',
    'ka_q_hist_1_explain': 'Juru tulis di Sumeria, Babilonia, dan Asiria menekan stilus buluh berbentuk baji ke tanah liat basah. Uniknya, kebakaran kuno yang menghancurkan bangunan kayu justru memanggang tablet tanah liat tersebut menjadi arsip keramik yang awet ribuan tahun.',
    'ka_q_hist_1_book_title': 'Sapiens: A Brief History of Humankind',
    'ka_q_hist_1_book_author': 'Yuval Noah Harari',
    'ka_q_hist_2_prompt': 'Bagaimana para pelaut Austronesia dan Polinesia kuno mengarungi ribuan kilometer samudra lepas tanpa kompas magnetik?',
    'ka_q_hist_2_opt_a': 'Membaca jalur bintang cakrawala, pola pembiasan alun gelombang laut & petunjuk awan/burung laut',
    'ka_q_hist_2_opt_b': 'Mengikuti parit kabel gunung berapi bawah laut',
    'ka_q_hist_2_opt_c': 'Hanyut secara acak mengikuti angin muson',
    'ka_q_hist_2_opt_d': 'Menggunakan sekstan kaca dan kronometer mekanis',
    'ka_q_hist_2_fact_title': 'Kompas Bintang Austronesia & Navigasi Gelombang',
    'ka_q_hist_2_explain': 'Navigator ulung menghafal 32 titik kompas bintang di cakrawala, merasakan pantulan gelombang silang dari pulau jauh melalui lambung perahu bercadik, dan mengenali pantulan hijau laguna di bagian bawah awan.',
    'ka_q_hist_2_book_title': 'The Wayfinders: Why Ancient Wisdom Matters',
    'ka_q_hist_2_book_author': 'Wade Davis',
    'ka_q_cult_1_prompt': 'Dalam warisan budaya Batik tulis Indonesia yang diakui UNESCO, apa fungsi utama alat tembaga "canting"?',
    'ka_q_cult_1_opt_a': 'Menorehkan lilin malam panas di atas kain sebagai perintang warna sebelum pencelupan',
    'ka_q_cult_1_opt_b': 'Memintal kapas mentah menjadi benang halus',
    'ka_q_cult_1_opt_c': 'Menggosok kain sutra dengan batu sungai',
    'ka_q_cult_1_opt_d': 'Merebus daun nila di dalam kuali tanah liat',
    'ka_q_cult_1_fact_title': 'Filosofi & Kriya Canting Batik Tulis Nusantara',
    'ka_q_cult_1_explain': 'Canting menampung lilin malam hangat dalam nyamplung tembaga bercerat halus. Pembatik melukis titik dan garis presisi yang menahan resapan warna celup, menghasilkan motif filosofis seperti Kawung dan Parang.',
    'ka_q_cult_1_book_title': 'Batik: Fabled Cloth of Java',
    'ka_q_cult_1_book_author': 'Inger McCabe Elliott',
    'ka_q_cult_2_prompt': 'Dalam filosofi kriya Jepang "Kintsugi", bagaimana mangkuk keramik yang retak atau pecah diperbaiki secara tradisional?',
    'ka_q_cult_2_opt_a': 'Direkatkan dengan pernis urushi bertabur bubuk emas, menghargai jejak perbaikan sebagai bagian kisah mangkuk',
    'ka_q_cult_2_opt_b': 'Dihancurkan menjadi bubuk untuk dicetak ulang',
    'ka_q_cult_2_opt_c': 'Ditutup cat hitam tebal agar retakannya tidak terlihat',
    'ka_q_cult_2_opt_d': 'Dijepit paku besi lalu dikubur di dalam pasir',
    'ka_q_cult_2_fact_title': 'Kintsugi & Filosofi Sambungan Emas Wabi-Sabi',
    'ka_q_cult_2_explain': 'Berasal dari Jepang abad ke-15, Kintsugi ("sambungan emas") merekatkan keramik pecah dengan getah pernis urushi alami dan memoles garis sambungannya dengan bubuk emas—merayakan ketangguhan dan ketidaksempurnaan alih-alih menyembunyikan luka.',
    'ka_q_cult_2_book_title': 'Wabi-Sabi for Artists, Designers, Poets & Philosophers',
    'ka_q_cult_2_book_author': 'Leonard Koren',
