    'bp_p_pat_1_title': 'Siklus Rotasi Fase 90°',
    'bp_p_pat_1_prompt': 'Perhatikan urutan rotasi piringan fase:  ◐  →  ◓  →  ◑  →  ?  Simbol mana yang melengkapi putaran 90° searah jarum jam?',
    'bp_p_pat_1_opt_a': '◒ (Setengah bawah terang)',
    'bp_p_pat_1_opt_b': '◐ (Setengah kiri terang)',
    'bp_p_pat_1_opt_c': '◓ (Setengah atas terang)',
    'bp_p_pat_1_opt_d': '● (Penuh terang)',
    'bp_p_pat_1_explain': 'Setiap langkah memutar sisi terang sebesar 90° searah jarum jam: Kiri (◐) → Atas (◓) → Kanan (◑) → Bawah (◒). Rotasi mental mengaktifkan memori kerja visual sebelum sesi fokus.',
    'bp_p_pat_2_title': 'Simetri Matriks & Paritas Isi',
    'bp_p_pat_2_prompt': 'Baris 1:  △  ▲  △   |   Baris 2:  ○  ●  ○   |   Baris 3:  □  ■  ?   Keping mana yang melengkapi Baris 3?',
    'bp_p_pat_2_opt_a': '□ (Persegi kosong)',
    'bp_p_pat_2_opt_b': '■ (Persegi berisi)',
    'bp_p_pat_2_opt_c': '○ (Lingkaran kosong)',
    'bp_p_pat_2_opt_d': '▲ (Segitiga berisi)',
    'bp_p_pat_2_explain': 'Setiap baris mempertahankan bentuk yang sama (segitiga, lingkaran, persegi) sambil menyusun paritas isi secara simetris: Kosong – Berisi – Kosong (□ ■ □).',
    'bp_p_seq_1_title': 'Langkah Spiral Botani Fibonacci',
    'bp_p_seq_1_prompt': 'Spiral bunga matahari dan runjung pinus tumbuh mengikuti deret:  1,  1,  2,  3,  5,  8,  13,  ?   Angka berapa selanjutnya?',
    'bp_p_seq_1_opt_a': '21 (8 + 13)',
    'bp_p_seq_1_opt_b': '19 (6 + 13)',
    'bp_p_seq_1_opt_c': '24 (11 + 13)',
    'bp_p_seq_1_opt_d': '26 (13 × 2)',
    'bp_p_seq_1_explain': 'Dalam deret Fibonacci, setiap suku merupakan jumlah dari dua angka sebelumnya: 8 + 13 = 21. Mengenali pola penjumlahan berulang membantu kesiapan fokus analitis.',
    'bp_p_seq_2_title': 'Progresi Selisih Bertingkat',
    'bp_p_seq_2_prompt': 'Perhatikan selisih yang bertambah pada deret:  2,  4,  7,  11,  16,  ?   Angka mana yang melanjutkan pola ini?',
    'bp_p_seq_2_opt_a': '22 (langkah +6)',
    'bp_p_seq_2_opt_b': '20 (langkah +4)',
    'bp_p_seq_2_opt_c': '21 (langkah +5)',
    'bp_p_seq_2_opt_d': '24 (langkah +8)',
    'bp_p_seq_2_explain': 'Selisih antar suku berurutan bertambah +1 di setiap langkah: +2, +3, +4, +5, sehingga suku berikutnya adalah 16 + 6 = 22.',
    'bp_p_spa_1_title': 'Lipatan Sisi Berhadapan Jaring Kubus 3D',
    'bp_p_spa_1_prompt': 'Pada jaring kubus 6-persegi berbentuk salib datar, ★ berada di persegi tengah dan ● berada 2 persegi di sebelah kanannya (dipisahkan 1 persegi tengah). Saat dilipat menjadi kubus 3D, di mana posisi ● terhadap ★?',
    'bp_p_spa_1_opt_a': 'Tepat pada sisi sejajar yang berhadapan langsung dengan ★',
    'bp_p_spa_1_opt_b': 'Menumpuk pada sisi yang sama dengan ★',
    'bp_p_spa_1_opt_c': 'Bersentuhan dengan tepi atas ★',
    'bp_p_spa_1_opt_d': 'Bersentuhan dengan tepi kiri ★',
    'bp_p_spa_1_explain': 'Pada jaring kubus ortogonal, dua persegi yang dipisahkan tepat satu persegi dalam garis lurus selalu terlipat 90° dua kali (total 180°) menjadi sisi berhadapan.',
    'bp_p_spa_2_title': 'Pencerminan Sumbu Cermin Vertikal',
    'bp_p_spa_2_prompt': 'Keping sudut berbentuk L menunjuk ke Atas dan Kanan (┗). Jika dicerminkan secara horizontal melewati garis cermin vertikal di sebelah kanannya, orientasi mana yang dihasilkan?',
    'bp_p_spa_2_opt_a': '┛ (Menunjuk Atas dan Kiri)',
    'bp_p_spa_2_opt_b': '┏ (Menunjuk Bawah dan Kanan)',
    'bp_p_spa_2_opt_c': '┓ (Menunjuk Bawah dan Kiri)',
    'bp_p_spa_2_opt_d': '┗ (Tetap Atas dan Kanan)',
    'bp_p_spa_2_explain': 'Pencerminan melewati garis vertikal mempertahankan arah vertikal (Atas tetap Atas) sambil membalik arah horizontal (Kanan berbalik menjadi Kiri: ┗ → ┛).',
    'seren_prompt_evening_quiet_sanctuary': 'Ruang tenang ini tidak menuntut apa pun dari Anda—cukup beristirahat.',
