    'exp_dcp_sketch_1_title': 'Kontur Cangkir & Uap Hangat',
    'exp_dcp_sketch_1_prompt': 'Gambar cangkir, gelas, atau teko terdekat dengan satu garis mengalir tanpa mengangkat pena selama semenit, lalu beri arsiran ringan.',
    'exp_dcp_sketch_1_tip': 'Garis yang tidak sempurna terasa lebih hangat daripada garis penggaris.',
    'exp_dcp_sketch_2_title': 'Bingkai Jendela Saku',
