    'exp_dcp_sketch_2_tip': 'Fokus pada bentuk besar dulu; detail kecil sifatnya opsional.',
    'exp_dcp_sketch_3_title': 'Tiga Benda Sehari-hari',
    'exp_dcp_sketch_3_prompt': 'Pilih tiga benda kecil dalam jangkauan tangan (kunci, daun, sendok, headphone) lalu sketsa berdampingan sebagai ikon studi kecil.',
    'exp_dcp_sketch_3_tip': 'Kertas bekas atau pinggiran buku catatan pun sudah cukup.',
    'exp_dcp_poetry_1_title': 'Haiku Cuaca Tiga Baris',
    'exp_dcp_poetry_1_prompt': 'Tulis tiga baris singkat yang menangkap warna langit hari ini, suhu udara, dan satu suara pelan di dalam ruangan.',
    'exp_dcp_poetry_1_tip': 'Tak perlu menghitung suku kata secara kaku jika ada irama yang lebih pas.',
    'exp_dcp_poetry_2_title': 'Momen Enam Kata',
    'exp_dcp_poetry_2_prompt': 'Rangkum suasana jam ini menjadi tiga kalimat mini yang masing-masing terdiri dari enam kata.',
    'exp_dcp_poetry_2_tip': 'Kata benda dan kata kerja konkret terasa lebih hidup daripada kata sifat panjang.',
    'exp_dcp_poetry_3_title': 'Surat untuk Benda Tenang',
