    'exp_dcp_poetry_3_tip': 'Hangat dan ringan jauh lebih baik daripada kaku dan sempurna.',
    'exp_dcp_obs_1_title': 'Lima Warna Tenang di Sekitar',
    'exp_dcp_obs_1_prompt': 'Amati ruangan pelan-pelan dan sebutkan lima nuansa warna spesifik yang belum sempat kamu sadari hari ini (misalnya hijau sage redup atau bayangan abu).',
