    'exp_dcp_obs_2_tip': 'Dengung kulkas atau kicau burung jauh tetap menjadi catatan lapangan yang menarik.',
    'exp_dcp_obs_3_title': 'Inventaris Tekstur & Cahaya',
    'exp_dcp_obs_3_prompt': 'Deskripsikan tiga permukaan di dekatmu—keramik halus, serat kayu kasar, katun lembut—dan bagaimana cahaya menyentuh tepinya.',
